function hasDoctorApplicationDraft(){try{return Boolean(sessionStorage.getItem('caresync-doctor-application-draft'))}catch{return false}}
function distanceKm(a:Point,b:Point){const r=6371,rad=(x:number)=>x*Math.PI/180,lat=rad(b.latitude-a.latitude),lon=rad(b.longitude-a.longitude);const h=Math.sin(lat/2)**2+Math.cos(rad(a.latitude))*Math.cos(rad(b.latitude))*Math.sin(lon/2)**2;return 2*r*Math.atan2(Math.sqrt(h),Math.sqrt(1-h))}

function Brand(){return <Link className="brand" to="/" aria-label="CareSync home"><span className="brand-mark"><svg viewBox="0 0 48 48" aria-hidden="true"><path className="brand-loop brand-loop-top" d="M15.2 15.7a13.1 13.1 0 0 1 21.1.5"/><path className="brand-loop brand-loop-bottom" d="M32.8 32.3a13.1 13.1 0 0 1-21.1-.5"/><path className="brand-arrow" d="m32.7 10.7 4.1 5.5-6.8.4M15.3 37.3l-4.1-5.5 6.8-.4"/><path className="brand-plus" d="M24 18.5v11m-5.5-5.5h11"/></svg></span><span className="brand-word">Care<span className="brand-sync">Sync</span></span></Link>}
