  useEffect(()=>{if(!supabase)return;let active=true;void supabase.from('doctor_profiles').select('clinic_name,facility_id').eq('verification_status','approved').limit(500).then(({data,error})=>{if(!active||error||!data)return;const clinics=new Set(data.map((row:any)=>row.facility_id||String(row.clinic_name||'').trim().toLowerCase()).filter(Boolean));setNetwork({clinics:clinics.size,doctors:data.length})});return()=>{active=false}},[])
