    <nav className="landing-nav">
      <Brand/>
      <div className="landing-links"><a href="#services">What you can do</a><Link to="/about">About us</Link></div>
      <div className="nav-actions"><Link className="btn btn-ghost" to="/login">Log in</Link><Link className="btn btn-primary btn-sm" to="/login">Get started <ArrowRight size={15}/></Link></div>
    </nav>
